contract InvMutTest {
    C c;
    Neuron n;

    constructor(C _c) {
        c = _c;
    }

    // single public entry that takes parameters to drive mint purchases
    function run(address neuronAddress, uint256 tokenId, uint256 quantity) public payable {
        require(quantity > 0);
        // instantiate neuron instance in C by calling instantiateNeuronContract as owner
        // The test contract is the deployer of C, so it is _ownerAddress and isAdmin by constructor comment.
        // set up neuron instance pointer in C
        c.instantiateNeuronContract(neuronAddress);
        n = Neuron(neuronAddress);

        // Pre-reads
        uint256 beforeBuyerBalance = c.balanceOf(address(this), tokenId);
        uint256 beforeNeuronTreasuryBalance = n.balanceOf(c.treasuryAddress());

        // Try to perform the mint (which calls Neuron.approveSpender and transferFrom)
        bool reverted;
        try c.mint(tokenId, quantity) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Observables after attempt
        uint256 afterBuyerBalance = c.balanceOf(address(this), tokenId);
        uint256 afterNeuronTreasuryBalance = n.balanceOf(c.treasuryAddress());

        // Compute price and conditions using only public getters of C and Neuron
        // Read item price and finiteSupply/itemsRemaining/dailyAllowance by calling public getters indirectly:
        // allGameItemAttributes is public array; its fields are not directly accessible, so derive conditions via calls that are public only: remainingSupply and uniqueTokensOutstanding and getAllowanceRemaining
        uint256 unique = c.uniqueTokensOutstanding();
        // When tokenId is out of bounds, c.mint should revert; otherwise further conditions apply.
        bool idInRange = tokenId < unique;

        uint256 remaining = 0;
        if (idInRange) {
            remaining = c.remainingSupply(tokenId);
        }

        // We cannot directly read itemPrice or dailyAllowance; but we can infer a necessary condition for success: Neuron.balanceOf(msg.sender) >= itemPrice*quantity
        // Check neuron's balance of this caller (this contract)
        uint256 buyerNRN = n.balanceOf(address(this));

        // General property to assert:
        // If mint succeeded (not reverted) then:
        //  - tokenId was in range
        //  - buyer's ERC1155 balance increased by exactly quantity
        //  - neuron's treasury balance increased (i.e., transfer happened) by some nonzero multiple equal to price
        // We can't compute price exactly, but can check that treasury balance did not decrease and that it increased when buyerNRN decreased.

        // Ensure: if not reverted then idInRange and afterBuyerBalance == beforeBuyerBalance + quantity and afterNeuronTreasuryBalance >= beforeNeuronTreasuryBalance
        assert(reverted || (idInRange && afterBuyerBalance == beforeBuyerBalance + quantity && afterNeuronTreasuryBalance >= beforeNeuronTreasuryBalance));
    }

    receive() external payable {}
}

