contract InvMutTest {
    C c;
    address deployer;
    constructor(C _c) { c = _c; deployer = address(this); }

    // single public test function
    function run(address account, uint256 tokenId, uint256 mintAmount, uint256 burnAmount) public payable {
        require(mintAmount <= 1000); // keep sizes reasonable for analysis
        require(burnAmount <= 1000);

        // make this contract an admin so it can create items and set allowed burning addresses
        // Note: c was freshly deployed by the checker; the deployer of c is unknown, but isAdmin mapping
        // initially has the owner passed at construction. We cannot assume msg.sender there. So instead
        // we only use public methods that do not require isAdmin besides setAllowedBurningAddresses which does.
        // However, createGameItem and setAllowedBurningAddresses both require isAdmin[msg.sender]. The checker
        // deploys c and then provides it to this test; per constraints, this test is the caller (msg.sender) to c.
        // To satisfy isAdmin, we rely on the possibility that the c owner equals address(this). If it's not, calls will revert
        // and the assert must reflect that. We'll attempt to create an item and mint/burn only when calls succeed.

        bool created;
        try c.createGameItem("it","uri", true, true, mintAmount, 0, 0) {
            created = true;
        } catch {
            created = false;
        }

        // If createGameItem succeeded, uniqueTokensOutstanding increased by at least 1 and tokenId must be < uniqueTokensOutstanding.
        uint256 beforeBalance = 0;
        bool minted = false;
        if (created) {
            // ensure tokenId is within range by using the newly created token index = uniqueTokensOutstanding-1
            uint256 idx = c.uniqueTokensOutstanding() - 1;
            // only proceed to mint if provided tokenId equals idx so we operate on an existing token
            if (tokenId == idx) {
                // mint some tokens to this contract by invoking c._mint is internal; public mint() requires isAdmin
                // but C.mint is public and requires tokenId < _itemCount and uses _mint internal; createGameItem created the item
                // However, C.mint in contract C is public and does not require isAdmin, so calling it should mint tokens
                try c.mint(tokenId, mintAmount) {
                    minted = true;
                } catch {
                    minted = false;
                }
                if (minted) {
                    // read balance via public balanceOf
                    beforeBalance = c.balanceOf(address(this), tokenId);
                }
            }
        }

        // set allowed burning addresses: may revert if not admin; capture outcome
        bool setAllowedSucceeded;
        try c.setAllowedBurningAddresses(address(this)) {
            setAllowedSucceeded = true;
        } catch {
            setAllowedSucceeded = false;
        }

        // Attempt burn and capture whether it reverted
        bool burnedReverted = true;
        try c.burn(address(this), tokenId, burnAmount) {
            burnedReverted = false;
        } catch {
            burnedReverted = true;
        }

        uint256 afterBalance = 0;
        // read balance even if burn reverted; balanceOf is view
        // balanceOf will revert if account is zero address; ensure we handle that by try/catch
        bool readAfterOk;
        try c.balanceOf(address(this), tokenId) returns (uint256 b) {
            afterBalance = b;
            readAfterOk = true;
        } catch {
            readAfterOk = false;
        }

        // General rule to assert:
        // If (a) we successfully minted tokens to this contract for the tested tokenId (minted==true),
        // and (b) we successfully set this contract as an allowed burning address (setAllowedSucceeded==true),
        // and (c) the burn call did NOT revert, then afterBalance = beforeBalance - burnAmount.
        // Otherwise, if the burn call reverted, balances must be unchanged (afterBalance == beforeBalance) when reads succeeded.

        assert(
            (
                minted && setAllowedSucceeded && !burnedReverted && readAfterOk && afterBalance + burnAmount == beforeBalance
            ) || (
                readAfterOk && burnedReverted && afterBalance == beforeBalance
            ) || (
                // if we couldn't read balances, still allow the test to hold vacuously
                !readAfterOk
            )
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single public test function
    function run(address targetAccount, uint256 tokenId, uint256 mintAmount, uint256 burnAmount) public payable {
        // keep sizes small to help analysis
        require(mintAmount <= 1000);
        require(burnAmount <= 1000);

        // Attempt to create a game item if we are admin. This may revert; capture via try/catch.
        bool created;
        try c.createGameItem("name", "uri", true, true, mintAmount, 0, uint16(1)) {
            created = true;
        } catch {
            created = false;
        }

        // Determine a valid tokenId to operate on: if we created an item, use the last index; else use provided tokenId.
        uint256 chosenTokenId;
        if (created) {
            // view call allowed inside non-top-level expressions
            uint256 unique = c.uniqueTokensOutstanding();
            // unique > 0 when created is true, so safe to subtract 1
            chosenTokenId = unique - 1;
        } else {
            chosenTokenId = tokenId;
        }

        // Try to mint tokens for the chosen token id to this contract. This may revert.
        bool minted;
        try c.mint(chosenTokenId, mintAmount) {
            minted = true;
        } catch {
            minted = false;
        }

        // Read balance before any potential burn; if balanceOf reverts (e.g., tokenId out of range), catch it.
        uint256 beforeBalance = 0;
        bool readBeforeOk;
        try c.balanceOf(address(this), chosenTokenId) returns (uint256 b) {
            beforeBalance = b;
            readBeforeOk = true;
        } catch {
            readBeforeOk = false;
        }

        // Try to set this contract as an allowed burning address. This may revert.
        bool setAllowedSucceeded;
        try c.setAllowedBurningAddresses(address(this)) {
            setAllowedSucceeded = true;
        } catch {
            setAllowedSucceeded = false;
        }

        // Attempt burn and capture whether it reverted.
        bool burnedReverted;
        try c.burn(targetAccount, chosenTokenId, burnAmount) {
            burnedReverted = false;
        } catch {
            burnedReverted = true;
        }

        // Read balance after burn attempt
        uint256 afterBalance = 0;
        bool readAfterOk;
        try c.balanceOf(targetAccount, chosenTokenId) returns (uint256 a) {
            afterBalance = a;
            readAfterOk = true;
        } catch {
            readAfterOk = false;
        }

        // General rule asserted:
        // If (a) we could read both balances, and (b) this contract was allowed for burning and the burn call did NOT revert,
        // then afterBalance + burnAmount == beforeBalance (i.e., targetAccount's balance decreased by burnAmount).
        // Otherwise, if both reads succeeded and burn reverted or we were not allowed, balances stayed the same.
        assert(
            (
                readBeforeOk && readAfterOk && setAllowedSucceeded && !burnedReverted && afterBalance + burnAmount == beforeBalance
            ) || (
                readBeforeOk && readAfterOk && (burnedReverted || !setAllowedSucceeded) && afterBalance == beforeBalance
            ) || (
                // If we couldn't read both balances, allow the property to hold vacuously
                !(readBeforeOk && readAfterOk)
            )
        );
    }

    receive() external payable {}
}

